<?php
declare(strict_types=1);require dirname(__DIR__).'/config/bootstrap.php';$user=require_role('guru');$pdo=db();$year=trim((string)($_GET['tahun_ajaran']??ACTIVE_ACADEMIC_YEAR));$stmt=$pdo->prepare('SELECT * FROM surah_curriculum WHERE tahun_ajaran=? ORDER BY level,urutan');$stmt->execute([$year]);$rows=$stmt->fetchAll();$byLevel=[];foreach($rows as $row)$byLevel[(int)$row['level']][]=$row;$pageTitle='Data Surat per Jenjang';require ROOT_PATH.'/includes/header.php';?>
<div class="page-head"><div><p class="eyebrow">Kurikulum Tahsin & Tahfizh</p><h1 class="page-title">Data Surat per Jenjang</h1><p class="page-description">Daftar surat dipisahkan per tahun ajaran agar riwayat kurikulum tetap terjaga.</p></div><button class="btn btn-primary" data-modal-open="surah-form">+ Tambah Surat</button></div><section class="card"><form method="get" class="filter-row"><div class="field"><label>Tahun Ajaran</label><input class="input" name="tahun_ajaran" value="<?= e($year) ?>" pattern="[0-9]{4}/[0-9]{4}"></div><button class="btn btn-soft">Tampilkan</button></form></section><section class="grid grid-3" style="margin-top:20px"><?php for($level=1;$level<=9;$level++):?><article class="card" style="padding:0;overflow:hidden"><div style="background:var(--green);color:#fff;padding:18px 20px"><small style="color:#bce8d2">JENJANG <?= $level ?></small><h2 style="margin:3px 0"><?= e(level_name($level)) ?></h2><span class="badge badge-green"><?= count($byLevel[$level]??[]) ?> surat</span></div><div style="padding:12px 20px"><div class="compact-list"><?php foreach($byLevel[$level]??[] as $surah):?><div class="compact-item"><span><strong><?= (int)$surah['urutan'] ?>.</strong> <?= e($surah['nama_surah']) ?></span><form action="<?= url('api/surah/index.php') ?>" method="post" data-ajax><?= csrf_field() ?><input type="hidden" name="action" value="delete"><input type="hidden" name="surah_id" value="<?= e($surah['id']) ?>"><button class="btn btn-danger btn-sm" data-confirm="Hapus surat ini?">×</button></form></div><?php endforeach;?><?php if(empty($byLevel[$level])):?><div class="empty" style="padding:25px 5px">Belum ada surat.</div><?php endif;?></div></div></article><?php endfor;?></section><div class="modal" id="surah-form"><div class="modal-card"><div class="modal-head"><div><p class="eyebrow">Kurikulum</p><h2>Tambah Surat</h2></div><button class="modal-close" data-modal-close>×</button></div><form action="<?= url('api/surah/index.php') ?>" method="post" data-ajax class="form-grid"><?= csrf_field() ?><input type="hidden" name="action" value="save"><div class="field"><label>Tahun Ajaran</label><input class="input" name="tahun_ajaran" value="<?= e($year) ?>" pattern="[0-9]{4}/[0-9]{4}" required></div><div class="field"><label>Level</label><select class="select" name="level"><?php for($level=1;$level<=9;$level++):?><option value="<?= $level ?>"><?= e(level_name($level)) ?></option><?php endfor;?></select></div><div class="field full"><label>Nama Surat</label><input class="input" name="nama_surah" required></div><div class="field"><label>Urutan</label><input class="input" type="number" name="urutan" min="1" required></div><button class="btn btn-primary field full">Simpan Surat</button></form></div></div><?php require ROOT_PATH.'/includes/footer.php';?>

